import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { updateDoc, getDoc, doc, onSnapshot, deleteField } from "@firebase/firestore"
import { firestore } from '../database/config';
import { useNavigate } from "react-router-dom";
import { debounce } from 'lodash'; // Import the debounce function

import ReactQuill from 'react-quill';

import './note.css';
import './quill.snow.css';

import { BiGroup } from 'react-icons/bi';
import { BsPersonPlus } from 'react-icons/bs';
import { TfiBackLeft } from 'react-icons/tfi';

import { toast } from 'react-toastify';



export default function NoteApp() {
  const navigate = useNavigate();

  const [noteText, setNoteText] = useState("");
  const [inputToken, setInputToken] = useState("");

  const location = useLocation();
  const noteID = location.state && location.state.noteID;
  const [noteTitle, setNoteTitle] = useState(location.state && location.state.noteTitle);

  const invite_succes_toast = () => toast.success("User invited", {
    autoClose: 1000,
    newestOnTop: true,
    closeOnClick: true,
    pauseOnHover: false,
    draggable: false,
    progress: undefined,
  });

  const invite_error_toast = () => toast.error("User not found", {
    autoClose: 1000,
    newestOnTop: true,
    closeOnClick: true,
    pauseOnHover: false,
    draggable: false,
    progress: undefined,
  });

  var toolbarOptions = [
    ['bold', 'italic', 'underline', 'strike'],        // toggled buttons
    ['blockquote', 'code-block'],

    [{ 'header': 1 }, { 'header': 2 }],               // custom button values
    [{ 'list': 'ordered' }, { 'list': 'bullet' }],
    [{ 'script': 'sub' }, { 'script': 'super' }],      // superscript/subscript
    [{ 'indent': '-1' }, { 'indent': '+1' }],          // outdent/indent
    [{ 'direction': 'rtl' }],                         // text direction

    [{ 'size': ['small', false, 'large', 'huge'] }],  // custom dropdown
    [{ 'header': [1, 2, 3, 4, 5, 6, false] }],

    [{ 'color': [] }, { 'background': [] }],          // dropdown with defaults from theme
    [{ 'font': [] }],
    [{ 'align': [] }],

    ['clean'],                                          // remove formatting button
  ];

  const module = {
    toolbar: toolbarOptions,
  };

  const handleGoBack = () => {
    navigate("/grid");
  }

  const handleInvite = async (token) => {

    // Check if user exists
    const userRef = doc(firestore, 'users', token);
    const docSnapshot = await getDoc(userRef);
    if (!docSnapshot.exists()) {
      console.log(`User with token ${token} doest not exists.`);
      return invite_error_toast(); // notify user
    }

    const collabRef = doc(firestore, 'collaboration', noteID);
    let documentData = [];

    try {
      // Fetch the document data
      const documentSnapshot = await getDoc(collabRef);
      if (documentSnapshot.exists()) {
        documentData = documentSnapshot.data();
        documentData[token] = token;

        // Create a new document with the modified data
        await updateDoc(collabRef, documentData);

        console.log('Updated document:', documentData);
        setInputToken(""); // clear variable
        invite_succes_toast(); // notify user
      } else {
        console.log('Document does not exist');
      }
    } catch (error) {
      console.error('Error fetching document:', error);
    }

    const noteRef = doc(firestore, 'notes', noteID);
    try {
      await updateDoc(noteRef, {
        user: deleteField()
      });
      console.log('Document deleted successfully.');
    } catch (error) {
      console.error('Error deleting field:', error);
    }
  };

  useEffect(() => {
    const noteRef = doc(firestore, 'notes', noteID);
    // Set up a real-time listener for the document
    const unsubscribe = onSnapshot(noteRef, (docSnapshot) => {
      if (docSnapshot.exists()) {
        const data = docSnapshot.data();
        console.log("Fetched as ", data.note);
        // Only update noteText if it's different from fetched data
        if (noteText !== data.note) {
          console.log("Fetched as ", data.note);
          setNoteText(data.note);
        }
        // Always update noteTitle
        setNoteTitle(data.title);

      } else {
        console.log('Document not found');
      }
    });

    return () => {
      unsubscribe();
    };
  }, []);

  const debouncedHandleUpload = debounce(async (newNoteText, newNoteTitle) => {
    const noteRef = doc(firestore, 'notes', noteID);
    try {
      await updateDoc(noteRef, {
        note: newNoteText,
        title: newNoteTitle,
      });
      console.log("Document successfully updated!");
    } catch (error) {
      console.error("Error updating document: ", error);
    }
  }, 20);

  const handleTextChange = (newNoteText) => {
    if (noteText !== newNoteText) {
      console.log("Upload as ", newNoteText);
      debouncedHandleUpload(newNoteText, noteTitle);
    }
  };

  const handleTitleChange = async (newNoteTitle) => {
    const noteRef = doc(firestore, 'notes', noteID);
    try {
      await updateDoc(noteRef, {
        title: newNoteTitle,
      });
      console.log("Document successfully updated!");
    } catch (error) {
      console.error("Error updating document: ", error);
    }
  };


  return (
    <div className="main_container">
      <div className="group-container">
        <i onClick={() => handleGoBack}> <BiGroup /> </i>
        <input className="input_token" type="text" placeholder="TOKEN OF COLLABORATOR" value={inputToken} onChange={(e) => setInputToken(e.target.value)} />
        <button className="invite_btn" onClick={() => handleInvite(inputToken)}> <BsPersonPlus /> </button>
      </div>
      <div className="group-container">
        <input className="input_title" type="text" value={noteTitle} placeholder="Title" onChange={(e) => handleTitleChange(e.target.value)} />
        <button className="back_button" onClick={handleGoBack}> <TfiBackLeft /> </button>
      </div>
      <ReactQuill
        modules={module}
        theme="snow"
        value={noteText}
        onChange={handleTextChange}
      />
    </div>
  );
}


